Tests all of the AccountsWithSessions system public static async Task AccountsWithSessionsTest()
{ var directory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "PariahCybersecTest", "TestFilesAsync"); if (Directory.Exists(directory)) { Directory.Delete(directory, true); Console.WriteLine("Directory and its contents reset."); } Directory.CreateDirectory(directory); Console.WriteLine(directory); string username = "testUser"; var password = "testPassword123".ToSecureData(); // Convert to SecureString string recoveryPassword = "recoveryPassword123"; // Recovery password // Initialize the object that has the methods var userManagement = new DataHandler.AccountsWithSessions(); // Setup files (Initialize JSON structure) await userManagement.SetupFiles(directory); // Create a user var recoveryKey = await userManagement.CreateUser(username, password, directory); Console.WriteLine($"User created. Recovery key: {recoveryKey.ConvertToString()}"); // Login the user var loginResult = await userManagement.LoginUser(username, directory, password, true); Console.WriteLine($"User logged in. Session ID: {loginResult.Item2.SessionID}"); // Validate the session bool isSessionValid = await userManagement.ValidateSession(loginResult.Item2, loginResult.Item1); Console.WriteLine($"Is session valid: {isSessionValid}"); // Reset password var newPassword = "newPassword123".ToSecureData(); await userManagement.ResetPassword(loginResult.Item2, loginResult.Item1, newPassword, recoveryKey); Console.WriteLine("Password reset successfully."); // Logout user (Remove if testing remove account, you need to be logged in to remove your acc) await userManagement.LogoutUser(loginResult.Item2, loginResult.Item1); Console.WriteLine("User logged out."); // Remove account await userManagement.RemoveAccount(loginResult.Item2, loginResult.Item1); Console.WriteLine("Account removed successfully.");
}

EasyPQC/Examples/EasyPQCTest.FileTest.ht.description:
Packs and unpacks a file (be sure to set filepath, filepath2 and output!)public void FileTest()
{ var filePath = "File Here" var fileOutput = @"TestFiles\"; // Generate a valid key pair var (publicKey, privateKey) = EasyPQC.Signatures.CreateKeys().Result; // Pack the file var pack = EasyPQC.FileOperations.PackFiles( filePath, fileOutput, privateKey, "Password".ToSecureData(), null, EasyPQC.FileOperations.CompressionLevel.Fast, true ).Result; Console.WriteLine("Packed file: " + pack); // Unpack the file var unpack = EasyPQC.FileOperations.UnpackFile( pack, fileOutput, publicKey, null, EasyPQC.FileOperations.CompressionLevel.Fast, "Password".ToSecureData() ).Result; Console.WriteLine("Unpacked file: " + unpack); // Test with a wrong password var falseUnpack = EasyPQC.FileOperations.UnpackFile( pack, fileOutput, publicKey, null, EasyPQC.FileOperations.CompressionLevel.Fast, "WrongPassword".ToSecureData() ).Result; Console.WriteLine("Unpacked file with wrong password: " + falseUnpack);
}

EasyPQC/Examples/EasyPQCTest.KeysMsgTest.description:
A fun way to imagine how the key system would be used for a Matrix style clientpublic void KeysMsgTest()
{ var members = new[] { "Kirito", "Asuna", "Klein", "Lisbeth", "Silica" }; var publicKeys = new Dictionary&lt;string, Dictionary&lt;string, byte[]&gt;&gt;(); var privateKeys = new Dictionary&lt;string, Dictionary&lt;string, byte[]&gt;&gt;(); // Step 1: Everyone generates a keypair foreach (var member in members) { var keys = EasyPQC.Keys.Initiate(); publicKeys[member] = keys.Item1; privateKeys[member] = keys.Item2; } Console.WriteLine("Everyone has generated their keys!\n"); // Step 2: Everyone (except Kirito) establishes a shared key with Kirito foreach (var member in members) { if (member == "Kirito") continue; var shared = EasyPQC.Keys.CreateSecret(publicKeys["Kirito"]); var sharedSecret = shared.key; Console.WriteLine($"🔐 {member} → Kirito:"); Console.WriteLine($" Shared Secret: {Convert.ToBase64String(sharedSecret)}"); // Simulating message send using the shared key Console.WriteLine($" Message from {member}: \"Hey Kirito, let's meet up at the mall!\"\n"); } Console.WriteLine("SAO Mall Chat setup complete! 🎉");
}

